export function createBrowserLocalRepository(getActor: () => Actor | null): WorkManagementRepository { return new LocalWorkManagementRepository(typeof window === 'undefined' ? undefined : window.localStorage, getActor); }
export interface DemoSession { phId: string; actorId: string; }
export function loadBrowserDemoSession(): DemoSession | null { if (typeof window === 'undefined') return null; try { const value = JSON.parse(window.localStorage.getItem(SESSION_KEY) ?? 'null') as DemoSession | null; return value && typeof value.phId === 'string' && typeof value.actorId === 'string' ? value : null; } catch { return null; } }
export function saveBrowserDemoSession(session: DemoSession) { if (typeof window !== 'undefined') window.localStorage.setItem(SESSION_KEY, JSON.stringify(session)); }
